// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading to prevent flickering
const { fontFamily: interFamily } = loadInter();



export type TypewriterStoryboardProps = Record<string, any>;

const TypewriterStoryboard: React.FC<TypewriterStoryboardProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  firstPhrase = "Introducing Malloy OS",
  secondPhrase = "A new class of Intelligence",
  textColor = "#000000",
  cursorColor = "#000000",
  fontSize = 80,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate strict frame boundaries based on percentages of total duration
  // This ensures the 4-scene animation scales perfectly with any duration chosen by the user.
  const totalFrames = durationInSeconds * fps;
  const p1 = Math.floor(totalFrames * 0.18); // Scene 1: Finish typing phrase 1
  const p2 = Math.floor(totalFrames * 0.38); // Scene 1 Hold: Pause to read
  const p3 = Math.floor(totalFrames * 0.48); // Transition: Finish deleting phrase 1
  const p4 = Math.floor(totalFrames * 0.58); // Scene 2: Hold empty (just cursor)
  const p5 = Math.floor(totalFrames * 0.85); // Scene 3: Finish typing phrase 2

  let displayedText = "";
  let isMoving = false;
  let showCursor = true;

  // State Machine for the 4 storyboard scenes
  if (frame < p1) {
    // Typing Phrase 1
    const progress = frame / p1;
    const chars = Math.floor(firstPhrase.length * progress);
    displayedText = firstPhrase.substring(0, chars);
    isMoving = true;
  } else if (frame < p2) {
    // Scene 1: Static Phrase 1
    displayedText = firstPhrase;
    isMoving = false;
  } else if (frame < p3) {
    // Deleting Phrase 1
    const progress = (frame - p2) / (p3 - p2);
    const charsRemaining = Math.floor(firstPhrase.length * (1 - progress));
    displayedText = firstPhrase.substring(0, charsRemaining);
    isMoving = true;
  } else if (frame < p4) {
    // Scene 2: Empty state with blinking cursor
    displayedText = "";
    isMoving = false;
  } else if (frame < p5) {
    // Scene 3: Typing Phrase 2
    const progress = (frame - p4) / (p5 - p4);
    const chars = Math.floor(secondPhrase.length * progress);
    displayedText = secondPhrase.substring(0, chars);
    isMoving = true;
  } else {
    // Scene 4: Final phrase held
    displayedText = secondPhrase;
    isMoving = false;
    
    // Hide cursor in the final 5% of the video to match Scene 4 of the storyboard
    if (frame > totalFrames * 0.95) {
      showCursor = false;
    }
  }

  // Deterministic cursor blinking logic (no Math.random, no state)
  const blinkRate = Math.floor(fps / 2.5); // Blink roughly every 0.4 seconds
  let cursorOpacity = 0;
  
  if (showCursor) {
    if (isMoving) {
      // Cursor stays solid while actively typing or deleting
      cursorOpacity = 1; 
    } else {
      // Cursor blinks when paused
      cursorOpacity = Math.floor(frame / blinkRate) % 2 === 0 ? 1 : 0;
    }
  }

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        justifyContent: "center", 
        alignItems: "center",
        transition: "none" 
      }}
    >
      <div
        style={{
          fontFamily: interFamily,
          fontSize: `${fontSize}px`,
          color: textColor,
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          fontWeight: 400,
          letterSpacing: "-0.02em",
          maxWidth: width * 0.8,
          textAlign: "center",
          lineHeight: 1.2,
          whiteSpace: "pre-wrap",
          transition: "none",
        }}
      >
        <span>{displayedText}</span>
        <span
          style={{
            borderRight: `${Math.max(3, fontSize * 0.05)}px solid ${cursorColor}`,
            opacity: cursorOpacity,
            marginLeft: "2px",
            height: "1.1em",
            display: "inline-block",
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TypewriterStoryboard;